create table users(id bigserial primary key,name varchar(120) not null,email varchar(180) not null unique,phone varchar(40),password_hash varchar(255) not null,role varchar(30) not null,active boolean not null default true);
create table officer_profiles(id bigserial primary key,user_id bigint not null unique references users(id),employee_id varchar(80) not null unique,department varchar(150),designation varchar(150),district varchar(100),office_name varchar(180),active boolean not null default true);
create table parcels(id bigserial primary key,survey_number varchar(120) not null unique,district varchar(100) not null,village varchar(120) not null,area double precision not null,latitude double precision,longitude double precision);
create table ownerships(id bigserial primary key,user_id bigint not null references users(id),parcel_id bigint not null references parcels(id),ownership_percentage double precision not null,unique(user_id,parcel_id));
create table acquisition_cases(id bigserial primary key,case_number varchar(100) not null unique,parcel_id bigint not null references parcels(id),project_name varchar(200),affected_area double precision not null,status varchar(50) not null,created_at timestamp not null);
create table acquisition_events(id bigserial primary key,acquisition_case_id bigint not null references acquisition_cases(id),status varchar(50) not null,remarks varchar(1000),event_time timestamp not null,created_by bigint not null references users(id));
create table compensations(id bigserial primary key,case_id bigint not null unique references acquisition_cases(id),assessed_amount double precision not null,approved_amount double precision not null,status varchar(50));
create table payments(id bigserial primary key,compensation_id bigint not null references compensations(id),amount double precision not null,transaction_reference varchar(150),status varchar(30) not null,paid_at timestamp);
create table hearings(id bigserial primary key,acquisition_case_id bigint not null references acquisition_cases(id),hearing_date timestamp,location varchar(250),status varchar(40),remarks varchar(1000));
create table documents(id bigserial primary key,acquisition_case_id bigint not null references acquisition_cases(id),document_type varchar(100),filename varchar(255),storage_path varchar(500),uploaded_at timestamp not null,uploaded_by bigint not null references users(id));
create table grievances(id bigserial primary key,acquisition_case_id bigint not null references acquisition_cases(id),submitted_by bigint not null references users(id),subject varchar(255),description text,status varchar(40) not null,resolution text,created_at timestamp not null,resolved_at timestamp);
create table notifications(id bigserial primary key,user_id bigint not null references users(id),message varchar(1000),notification_type varchar(100),read_status boolean not null default false,created_at timestamp not null);
create table audit_logs(id bigserial primary key,user_id bigint not null references users(id),action varchar(150),entity_type varchar(100),entity_id bigint,previous_value text,new_value text,created_at timestamp not null);
create index idx_cases_district on acquisition_cases(parcel_id); create index idx_ownership_user on ownerships(user_id); create index idx_events_case on acquisition_events(acquisition_case_id); create index idx_grievances_user on grievances(submitted_by);
